import os, sys, select, time, json, fcntl, termios, struct
def run(args, answers, cwd=None, timeout=8, env=None):
    pid, fd = os.forkpty()
    if pid == 0:
        if cwd: os.chdir(cwd)
        e = dict(os.environ); e.pop('NO_COLOR', None)
        if env: e.update(env)
        os.execve('/workspace/executable', ['zk']+args, e)
    # set window size
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', 24, 80, 0, 0))
    out=b''; ai=0; start=time.time(); last=time.time()
    while time.time()-start<timeout:
        r,_,_=select.select([fd],[],[],0.2)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d; last=time.time()
            if b'\x1b[6n' in d:
                os.write(fd, b'\x1b[1;1R')
        else:
            if ai<len(answers) and time.time()-last>0.3:
                os.write(fd, answers[ai]); ai+=1; last=time.time()
            elif time.time()-last>1.5:
                break
    try:
        os.waitpid(pid, os.WNOHANG)
    except ChildProcessError: pass
    try: os.close(fd)
    except: pass
    return out
if __name__=='__main__':
    args=json.loads(sys.argv[1]); answers=[a.encode() for a in json.loads(sys.argv[2])]
    cwd=sys.argv[3] if len(sys.argv)>3 and sys.argv[3] else None
    sys.stdout.buffer.write(run(args,answers,cwd))
PYEOF
